    private Commerce.ShoppingCart _cart = null!;

    [TestInitialize]
    public void Setup() => _cart = new Commerce.ShoppingCart();

    // ──── AddItem ────

    [TestMethod]
    public void AddItem_SingleItem_IncreasesItemCount()
    {
        _cart.AddItem("SKU-001", 9.99m, 1);
        Assert.AreEqual(1, _cart.ItemCount);
    }

    [TestMethod]
    public void AddItem_MultipleItems_TracksAll()
    {
        _cart.AddItem("A", 5m, 1);
        _cart.AddItem("B", 10m, 2);
        Assert.AreEqual(2, _cart.ItemCount);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public void AddItem_NullSku_Throws()
    {
        _cart.AddItem(null!, 5m, 1);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentException))]
    public void AddItem_EmptySku_Throws()
    {
        _cart.AddItem("", 5m, 1);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentOutOfRangeException))]
    public void AddItem_NegativePrice_Throws()
    {
        _cart.AddItem("SKU", -1m, 1);
    }

    [TestMethod]
    [ExpectedException(typeof(ArgumentOutOfRangeException))]
    public void AddItem_ZeroQuantity_Throws()
    {
        _cart.AddItem("SKU", 5m, 0);
    }

    // ──── RemoveItem ────

    [TestMethod]
    public void RemoveItem_ExistingItem_ReturnsTrue()
    {
        _cart.AddItem("SKU-001", 10m, 1);
        Assert.IsTrue(_cart.RemoveItem("SKU-001"));
    }

    [TestMethod]
    public void RemoveItem_ExistingItem_DecreasesCount()
    {
        _cart.AddItem("SKU-001", 10m, 1);
        _cart.RemoveItem("SKU-001");
        Assert.AreEqual(0, _cart.ItemCount);
    }

    [TestMethod]
    public void RemoveItem_NonExistentItem_ReturnsFalse()
    {
        Assert.IsFalse(_cart.RemoveItem("NOPE"));
    }

    [TestMethod]
    public void RemoveItem_RemovesDuplicateSkus()
    {
        _cart.AddItem("SKU-001", 10m, 1);
        _cart.AddItem("SKU-001", 10m, 2);
        _cart.RemoveItem("SKU-001");
        Assert.AreEqual(0, _cart.ItemCount);
    }

    // ──── GetTotal ────

    [TestMethod]
    public void GetTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0m, _cart.GetTotal());
    }

    [TestMethod]
    public void GetTotal_SingleItem_ReturnsPriceTimesQty()
    {
        _cart.AddItem("A", 7.50m, 3);
        Assert.AreEqual(22.50m, _cart.GetTotal());
    }

    [TestMethod]
    public void GetTotal_MultipleItems_ReturnsSumOfLineItems()
    {
        _cart.AddItem("A", 10m, 2);  // 20
        _cart.AddItem("B", 5m, 4);   // 20
        Assert.AreEqual(40m, _cart.GetTotal());
    }

    [TestMethod]
    public void GetTotal_AfterRemoval_ExcludesRemovedItem()
    {
        _cart.AddItem("A", 10m, 1);
        _cart.AddItem("B", 20m, 1);
        _cart.RemoveItem("A");
        Assert.AreEqual(20m, _cart.GetTotal());
    }

    // ──── ApplyPromoCode ────

    [TestMethod]
    public void ApplyPromoCode_ValidCode_ReturnsTrue()
    {
        Assert.IsTrue(_cart.ApplyPromoCode("SAVE10"));
    }

    [TestMethod]
    public void ApplyPromoCode_InvalidCode_ReturnsFalse()
    {
        Assert.IsFalse(_cart.ApplyPromoCode("INVALID"));
    }

    [TestMethod]
    public void ApplyPromoCode_CaseInsensitive()
    {
        Assert.IsTrue(_cart.ApplyPromoCode("save10"));
    }

    [TestMethod]
    public void ApplyPromoCode_Save10_Applies10PercentDiscount()
    {
        _cart.AddItem("A", 100m, 1);
        _cart.ApplyPromoCode("SAVE10");
        Assert.AreEqual(90m, _cart.GetTotal());
    }

    [TestMethod]
    public void ApplyPromoCode_Save20_Applies20PercentDiscount()
    {
        _cart.AddItem("A", 50m, 2); // subtotal 100
        _cart.ApplyPromoCode("SAVE20");
        Assert.AreEqual(80m, _cart.GetTotal());
    }

    [TestMethod]
    public void ApplyPromoCode_Half_Applies50PercentDiscount()
    {
        _cart.AddItem("A", 60m, 1);
        _cart.ApplyPromoCode("HALF");
        Assert.AreEqual(30m, _cart.GetTotal());
    }

    [TestMethod]
    public void ApplyPromoCode_InvalidCode_NoDiscount()
    {
        _cart.AddItem("A", 100m, 1);
        _cart.ApplyPromoCode("BOGUS");
        Assert.AreEqual(100m, _cart.GetTotal());
    }

    [TestMethod]
    public void ApplyPromoCode_SecondCodeOverridesFirst()
    {
        _cart.AddItem("A", 100m, 1);
        _cart.ApplyPromoCode("SAVE10");
        _cart.ApplyPromoCode("SAVE20");
        Assert.AreEqual(80m, _cart.GetTotal());
    }
}
"}

